// Input: { tenantId, candidates: [isoString, ...] }
// Output: { rangeStart, rangeEnd, candidates } — the min/max window to
// pull events for, padded by 1 day on each side so the Google Calendar
// node's timeMin/timeMax comfortably covers every candidate slot.
const body = $input.first().json.body || {};
const candidates = Array.isArray(body.candidates) ? body.candidates : [];
if (candidates.length === 0) {
  return [{ json: { tenantId: body.tenantId, candidates: [], rangeStart: new Date().toISOString(), rangeEnd: new Date().toISOString() } }];
}
const times = candidates.map((c) => new Date(c).getTime()).filter((t) => !isNaN(t));
const minT = Math.min(...times) - 24 * 60 * 60 * 1000;
const maxT = Math.max(...times) + 24 * 60 * 60 * 1000;
return [{ json: { tenantId: body.tenantId, candidates, rangeStart: new Date(minT).toISOString(), rangeEnd: new Date(maxT).toISOString() } }];

// Input: this node's items are the calendar events in range; the
// upstream 'Compute Range' item (with candidates) is available via
// $('Compute Range').first().json.
// Output: { busy: [isoString, ...] } — every candidate that falls inside
// any existing event's [start, end) window, assuming a 30-minute slot
// length (matches DEFAULT_AVAILABILITY.slotMinutes in availability.js —
// adjust here if a tenant uses a different slot length).
const SLOT_MINUTES = 30;
const upstream = $('Compute Range').first().json;
const candidates = upstream.candidates || [];
const events = $input.all().map((item) => item.json).filter((e) => e && e.start);

const busy = candidates.filter((iso) => {
  const slotStart = new Date(iso).getTime();
  const slotEnd = slotStart + SLOT_MINUTES * 60 * 1000;
  return events.some((ev) => {
    const evStart = new Date(ev.start.dateTime || ev.start.date).getTime();
    const evEnd = new Date(ev.end?.dateTime || ev.end?.date || ev.start.dateTime || ev.start.date).getTime();
    return slotStart < evEnd && slotEnd > evStart; // overlap check
  });
});

return [{ json: { busy } }];
